const fs = require('fs');

function extract(filename) {
    const buffer = fs.readFileSync(filename);

    // e_phoff is at offset 32 (8 bytes, Big/Little endian - x86 is little endian)
    const e_phoff = Number(buffer.readBigUInt64LE(32));
    const e_phentsize = buffer.readUInt16LE(54);
    const e_phnum = buffer.readUInt16LE(56);

    const result = {};

    for (let i = 0; i < e_phnum; i++) {
        const offset = e_phoff + i * e_phentsize;
        const p_type = buffer.readUInt32LE(offset);
        // p_flags is at offset + 4
        const p_offset = Number(buffer.readBigUInt64LE(offset + 8));
        const p_vaddr = Number(buffer.readBigUInt64LE(offset + 16));
        // p_paddr is at offset + 24
        const p_filesz = Number(buffer.readBigUInt64LE(offset + 32));
        const p_memsz = Number(buffer.readBigUInt64LE(offset + 40));

        if (p_type === 1) { // PT_LOAD
            const base_addr = p_vaddr + 0x400000;
            let seg_data = Buffer.alloc(Number(p_memsz));
            buffer.copy(seg_data, 0, Number(p_offset), Number(p_offset) + Number(p_filesz));

            for (let addr_offset = 0; addr_offset < seg_data.length; addr_offset += 4) {
                if (addr_offset + 4 <= seg_data.length) {
                    const val = seg_data.readUInt32LE(addr_offset);
                    result[String(base_addr + addr_offset)] = val;
                }
            }
        }
    }

    console.log(JSON.stringify(result));
}

const args = process.argv.slice(2);
if (args.length > 0) {
    extract(args[0]);
} else {
    extract('/app/a.out');
}
